const trackedTransport=async(path:string,method?:string,body?:unknown)=>{const result=await transport(path,method,body);const p=progressRef.current;if(p){const next={...p,done:Math.min(p.total,p.done+1)};progressRef.current=next;setProgress(next)}return result};
const sync=async()=>{track('Syncing Google Sheets',sheetNames.length);try{const result=await loadWorkbook(trackedTransport);setData(result.workbook);setRevision(result.revision);setDirty(false);setMessage('v1.2 workbook synced')}finally{progressRef.current=null;setProgress(null)}};
